const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define locations and buffers
  const aswanDam = ee.Geometry.Point([32.9, 24.0]).buffer(5000); // 5km buffer
  const gerdDam = ee.Geometry.Point([35.1, 11.2]).buffer(5000); // 5km buffer

  // 2. Load VIIRS Nighttime Lights data for 2016
  const nightLights = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate('2016-01-01', '2016-12-31');

  // Check if collection has data
  const collectionSize = nightLights.size().getInfo();
  console.log(`Total images in 2016: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No nighttime lights data found for 2016.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Calculate mean composite for the year
  const composite = nightLights.select('avg_rad').mean();

  // 4. Calculate statistics for Aswan Dam
  const aswanStats = composite.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aswanDam,
    scale: 500,
    maxPixels: 1e9
  }).getInfo();

  const aswanBrightness = aswanStats['avg_rad_mean'];
  const aswanCount = aswanStats['avg_rad_count'];

  console.log(`Aswan Dam - Brightness: ${aswanBrightness}, Pixels: ${aswanCount}`);

  // 5. Calculate statistics for GERD
  const gerdStats = composite.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: gerdDam,
    scale: 500,
    maxPixels: 1e9
  }).getInfo();

  const gerdBrightness = gerdStats['avg_rad_mean'];
  const gerdCount = gerdStats['avg_rad_count'];

  console.log(`GERD - Brightness: ${gerdBrightness}, Pixels: ${gerdCount}`);

  // 6. Validation and final answer
  if (aswanCount === 0 || gerdCount === 0) {
    console.log('No valid pixels found for one or both locations.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (aswanBrightness === null || aswanBrightness === undefined || 
      gerdBrightness === null || gerdBrightness === undefined ||
      isNaN(aswanBrightness) || isNaN(gerdBrightness)) {
    console.log('Invalid calculation results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare brightness values
  console.log(`Comparison: Aswan (${aswanBrightness.toFixed(3)}) vs GERD (${gerdBrightness.toFixed(3)})`);

  if (aswanBrightness > gerdBrightness) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
